const mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);
function conflicts(x,list){return list.filter(y=>x.id!==y.id&&x.day===y.day&&mins(x.start)<mins(y.end)&&mins(y.start)<mins(x.end))}
function render(){const sorted=state.tasks.slice().sort((a,b)=>a.day.localeCompare(b.day)||a.start.localeCompare(b.start)), clashes=state.tasks.filter(x=>conflicts(x,state.tasks).length);
$('#app').innerHTML=`<div class="stats">${stat('计划活动',state.tasks.length)}${stat('已完成',state.tasks.filter(x=>x.done).length)}${stat('冲突活动',clashes.length)}</div><div class="grid"><div>${panel('我的周末时间轴',`<div class="timeline">${sorted.map(x=>`<div class="item"><div><span class="tag">${x.day} ${x.start}—${x.end}</span><h3 style="margin:10px 0 0">${esc(x.name)}</h3><p>${x.priority}优先级${conflicts(x,state.tasks).length?' · ⚠ 与其他活动冲突':''}</p></div><div class="row"><button data-action="${x.id}" class="small ${x.done?'selected':''}">${x.done?'已完成':'完成'}</button><button data-delete="${x.id}" class="small">删除</button></div></div>`).join('')||empty()}</div>`)}</div><div>${panel('留出时间，也留出空白',`<form id="schedule" class="stack">${field('活动名称','name','text','','required maxlength="40"')}<div class="fields">${select('哪一天','day',['周六','周日'])}${select('优先级','priority',['高','中','低'])}${field('开始时间','start','time','09:00','required')}${field('结束时间','end','time','10:00','required')}</div><button class="primary">加入计划</button></form>`)}${panel('调度提示',`<p>${clashes.length?'有活动重叠。删除或重新安排冲突项，试着先保留高优先级任务。':'目前没有冲突。试着为自由活动留一段空白。'}</p><p class="notice">新增的冲突活动会保留并标记，方便你主动做取舍。</p>`,'tint')}</div></div>`;
form('schedule',v=>{if(mins(v.end)<=mins(v.start))return toast('结束时间必须晚于开始时间');const x={...v,id:uid(),done:false};const has=conflicts(x,state.tasks).length;state.tasks.push(x);commit();toast(has?'已加入，但有时间冲突，请调整':'已加入周末计划')});actions('[data-action]',id=>{const x=state.tasks.find(x=>x.id===id);x.done=!x.done;commit()});$$('[data-delete]').forEach(b=>b.onclick=()=>{state.tasks=state.tasks.filter(x=>x.id!==b.dataset.delete);commit()})}render();
